    long long w;        //权值
    int l, r;           //左右孩子(节点下标),-1 表示空
    int sym;            // 叶子对应符号下标;内部节点为 -1
    Node(long long _w=0, int _l=-1, int _r=-1, int _sym=-1)
        : w(_w), l(_l), r(_r), sym(_sym) {}
