const int N = 1e5 + 5;
int n;
int f[N], c[N], cnt[N];
long long ans[N];
int main() {
    scanf("%d", &n);
    for (int i = 2; i <= n; i++) {
        scanf("%d", &f[i]);
        cnt[f[i]]++;
    }
    for (int i = 1; i <= n; i++)
        scanf("%d", &c[i]);
    for (int i = n; i >= 1; i--) {
        if (cnt[i] == 0)
